sparql:
PREFIX aidgo: <https://w3id.org/aidgo#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?article ?obligation (SUM(IF(?t = aidgo:CompletelySatisfies, 1, 0)) AS ?complete) (SUM(IF(?t = aidgo:PartiallySatisfies, 1, 0)) AS ?partial) (SUM(IF(?t = aidgo:NoAlignment, 1, 0)) AS ?gap)
WHERE {
  ?o a aidgo:LegalRequirement ; aidgo:articleReference ?article ; skos:prefLabel ?obligation .
  OPTIONAL { ?a a aidgo:AlignmentAssertion ; aidgo:legalRequirement ?o ; aidgo:alignmentType ?t . }
}
GROUP BY ?article ?obligation
ORDER BY ?article

PREFIX aidgo: <https://w3id.org/aidgo#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?article ?obligation ?justification
WHERE {
  ?o a aidgo:LegalRequirement ; aidgo:articleReference ?article ; skos:prefLabel ?obligation .
  FILTER NOT EXISTS { ?x aidgo:legalRequirement ?o ; aidgo:alignmentType ?t . FILTER(?t IN (aidgo:CompletelySatisfies, aidgo:PartiallySatisfies)) }
  OPTIONAL { ?g aidgo:legalRequirement ?o ; aidgo:alignmentType aidgo:NoAlignment ; aidgo:alignmentJustification ?justification . }
}
ORDER BY ?article

PREFIX aidgo: <https://w3id.org/aidgo#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?article ?clause ?basis ?gap
WHERE {
  ?a aidgo:alignmentType aidgo:PartiallySatisfies ; aidgo:legalRequirement ?o ; aidgo:technicalRequirement ?r ; aidgo:alignmentBasis ?b .
  OPTIONAL { ?a aidgo:alignmentGap ?gap }
  ?o aidgo:articleReference ?article . ?r dct:source ?clause .
  BIND(STRAFTER(STR(?b), "#") AS ?basis)
}
ORDER BY ?article ?clause

PREFIX aidgo: <https://w3id.org/aidgo#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?assertion ?type ?clause ?by ?activity ?basis
WHERE {
  ?o aidgo:articleReference "Art. 10(2)(f)" .
  ?a aidgo:legalRequirement ?o ; aidgo:alignmentType ?t ; dct:identifier ?assertion ; prov:wasAttributedTo ?by ; aidgo:alignmentBasis ?b ; prov:wasGeneratedBy ?act .
  OPTIONAL { ?a aidgo:technicalRequirement ?r . ?r dct:source ?clause }
  BIND(STRAFTER(STR(?t), "#") AS ?type) BIND(STRAFTER(STR(?b), "#") AS ?basis) BIND(STRAFTER(STR(?act), "#") AS ?activity)
}
